-- Migration 0013: the 2026-11 service catalogue (R9.1, docs/redesign/REFINEMENTS.md §1 and §4).
-- Retired divisions, services, packages and add-ons become inactive (never deleted: quotations, invoices and subscriptions
-- may reference them; admin keeps them readable). Products and technologies are unpublished. The new catalogue is upserted
-- with the same ids as seeds/base.sql (some ids are reused where the offer continues). Prices are integer US cents.
-- CMS copy that mentioned removed offers is updated only where it still equals the original seed (owner edits are kept).
-- Generated once from scripts/seeds/content/*; never edit after it has been applied.

-- USD must exist before priced rows reference it (fresh databases run migrations before the base seed; same row as the seed).
INSERT OR IGNORE INTO currencies (code, name, symbol, minor_digits, active, is_default) VALUES ('USD', 'US Dollar', '$', 2, 1, 1);

-- 1. Retire everything outside the catalogue
UPDATE service_categories SET status = 'inactive', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE status <> 'inactive' AND id NOT IN ('scat_websites', 'scat_business_software', 'scat_cross_platform_apps', 'scat_ai_data', 'scat_automation_integration', 'scat_add_ons');
UPDATE services SET status = 'inactive', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE status <> 'inactive' AND id NOT IN ('svc_websites__starter_website', 'svc_websites__business_website', 'svc_websites__ecommerce_website', 'svc_websites__custom_web_applications', 'svc_business_software__pos', 'svc_business_software__erp', 'svc_business_software__dashboards_reporting', 'svc_cross_platform_apps__cross_platform_development', 'svc_ai_data__ai_applications', 'svc_ai_data__data_analytics', 'svc_ai_data__document_processing', 'svc_automation_integration__process_automation', 'svc_automation_integration__payment_gateways', 'svc_automation_integration__api_development', 'svc_automation_integration__systems_integration', 'svc_add_ons__additional_pages', 'svc_add_ons__logo_design', 'svc_add_ons__copywriting', 'svc_add_ons__additional_languages', 'svc_add_ons__catalogue_upload');
UPDATE service_packages SET status = 'inactive', updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE status <> 'inactive' AND id NOT IN ('pkg_starter_website', 'pkg_business_website', 'pkg_ecommerce_website', 'pkg_custom_web_application', 'pkg_pos_inventory_system', 'pkg_custom_erp', 'pkg_business_dashboards', 'pkg_cross_platform_app', 'pkg_ai_assistant_integration', 'pkg_data_intelligence', 'pkg_document_processing', 'pkg_process_automation', 'pkg_payment_local_method', 'pkg_payment_card', 'pkg_api_development', 'pkg_systems_integration', 'pkg_additional_pages', 'pkg_logo_design', 'pkg_copywriting', 'pkg_additional_languages', 'pkg_catalogue_upload');
UPDATE package_addons SET active = 0, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE active = 1 AND id NOT IN ('pad_extra_page', 'pad_logo_design', 'pad_copywriting', 'pad_language', 'pad_catalogue_upload');
UPDATE products SET published = 0, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE published = 1;
UPDATE technologies SET published = 0 WHERE published = 1;

-- 2. Divisions and services
INSERT INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_websites', 'websites', 'Websites & Web Applications', 'Business websites, online stores and custom web applications that load fast and are easy to update.', '<p>We design and build websites for organisations that need more than a brochure. Every site is designed for phones first, loads quickly on mobile data, is set up for search and, from the Business Website up, lets your team update content without calling us.</p><p>For larger needs we build web applications on the same foundations: secure sign-in, role-based access, a database built around your records and local payment options.</p>', '[{"title":"Fast on real networks","body":"Pages are built to load quickly on mobile data, with optimised images and minimal scripts."},{"title":"Easy to update","body":"Business and e-commerce sites include a content editor so your team can change text and images."},{"title":"Found on search","body":"Clean structure, metadata, a sitemap and Search Console setup so people can find you."},{"title":"Ready to take payments","body":"Accept EcoCash, OneMoney, InnBucks and cards through Paynow when you sell online."}]', '["Mobile-first design for phones, tablets and desktops","Contact form and WhatsApp button","On-page SEO basics and an SSL certificate","Content editing on Business and E-commerce sites","Handover notes, and training where the package includes it"]', '[{"q":"Can I update the website myself?","a":"Yes, from the Business Website up. Those sites include a content editor and a short training session at handover. The Starter Website has no editor; we make changes for you during the support period."},{"q":"How long does a website take?","a":"A Starter Website takes 5 to 7 working days, a Business Website 2 to 3 weeks and an online store 4 to 6 weeks, once we have your content. Custom web applications are scheduled in the written quotation."},{"q":"Who owns the website?","a":"You do. On full payment, the content, design and code we wrote for you are yours, as set out in our service terms."}]', 'globe', 'active', 1, 10, 'Websites & Web Applications', 'Starter and business websites, e-commerce stores and custom web applications for organisations in Zimbabwe. Fast, mobile-first and easy to update.')
  ON CONFLICT(id) DO UPDATE SET slug = excluded.slug, name = excluded.name, summary = excluded.summary, description = excluded.description, benefits = excluded.benefits, deliverables = excluded.deliverables, faq = excluded.faq, icon = excluded.icon, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, seo_title = excluded.seo_title, seo_description = excluded.seo_description, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now');
