INSERT INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_business_software', 'business-software', 'Business Software & Systems', 'POS, inventory, ERP and reporting systems shaped around how your organisation works.', '<p>Off-the-shelf software often forces you to change how you work. We build business systems around your processes instead: point of sale and stock control, full business management platforms and the dashboards that show how the business is doing.</p><p>Systems support multiple branches and currencies, keep an audit trail of changes and can connect to the tools you already use.</p>', '[{"title":"Fits your process","body":"Workflows, approvals and reports follow how your team already works."},{"title":"Multi-currency by design","body":"USD and ZWG amounts are kept separate and reported correctly."},{"title":"Clear audit trail","body":"Every important change records who did it and when."},{"title":"Grows in stages","body":"Start with the module you need most and add others as you grow."}]', '["Process mapping and requirements document","Web-based system with role-based access","Data migration from spreadsheets or existing systems","Reports and exports","Staff training and user guides"]', '[{"q":"Can you move our data from spreadsheets?","a":"Yes. Data migration is part of most projects. We clean and import your existing records and check the totals with you before go-live."},{"q":"Does it work across branches?","a":"Yes. Systems can run across several branches with each user seeing only what their role allows."}]', 'layers', 'active', 1, 20, 'Business Software: POS, ERP & Reporting Systems', 'POS and inventory systems, custom ERP and business management platforms, and reporting dashboards built around your processes.')
  ON CONFLICT(id) DO UPDATE SET slug = excluded.slug, name = excluded.name, summary = excluded.summary, description = excluded.description, benefits = excluded.benefits, deliverables = excluded.deliverables, faq = excluded.faq, icon = excluded.icon, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, seo_title = excluded.seo_title, seo_description = excluded.seo_description, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now');
