  ON CONFLICT(id) DO UPDATE SET category_id = excluded.category_id, slug = excluded.slug, name = excluded.name, summary = excluded.summary, pricing_model = excluded.pricing_model, price_minor = excluded.price_minor, currency = excluded.currency, status = excluded.status, sort_order = excluded.sort_order, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now');
INSERT INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_cross_platform_apps', 'cross-platform-apps', 'Cross-Platform Application Development', 'One codebase for Android, iOS, Windows, macOS and Linux, built for real networks and real devices.', '<p>We build one application from a single codebase and release it on the platforms your users have: Android, iOS, Windows, macOS and Linux. One codebase keeps the cost of building and maintaining the app down while every platform gets the same features.</p><p>Apps are designed for the devices people actually use, including mid-range Android phones and patchy connections, and can keep working offline and sync when a connection returns.</p>', '[{"title":"One codebase, five platforms","body":"Android, iOS, Windows, macOS and Linux from the same code, so features ship everywhere together."},{"title":"Offline-capable","body":"Apps can keep working without signal and sync data when the connection returns."},{"title":"Store-ready","body":"We prepare listings, screenshots and releases for the app stores you publish to."},{"title":"Connected to your systems","body":"Apps talk to your existing databases, payment methods and business software through secure APIs."}]', '["User experience and interface design","One application released for the platforms you choose","Back-end API and admin dashboard where needed","Testing on real devices","App store publishing support"]', '[{"q":"Which platforms are supported?","a":"Android, iOS, Windows, macOS and Linux. You choose which ones to release on first; adding another later reuses the same code."},{"q":"Can the app work without internet?","a":"Yes. Offline support is planned during design so data is stored safely on the device and synced later."}]', 'smartphone', 'active', 1, 30, 'Cross-Platform App Development: Android, iOS & Desktop', 'One codebase for Android, iOS, Windows, macOS and Linux apps, with offline support, app store publishing and secure back-ends.')
  ON CONFLICT(id) DO UPDATE SET slug = excluded.slug, name = excluded.name, summary = excluded.summary, description = excluded.description, benefits = excluded.benefits, deliverables = excluded.deliverables, faq = excluded.faq, icon = excluded.icon, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, seo_title = excluded.seo_title, seo_description = excluded.seo_description, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now');
