  ON CONFLICT(id) DO UPDATE SET category_id = excluded.category_id, slug = excluded.slug, name = excluded.name, summary = excluded.summary, pricing_model = excluded.pricing_model, price_minor = excluded.price_minor, currency = excluded.currency, status = excluded.status, sort_order = excluded.sort_order, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now');
INSERT INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_ai_data', 'ai-data', 'AI, Data & Intelligence', 'Practical AI assistants, analytics and document processing that answer real business questions.', '<p>Most organisations already hold the data they need to make better decisions; it is just spread across systems and spreadsheets. We bring it together, clean it and present it in a form your team will use.</p><p>Where AI helps, we add it in practical ways: assistants that answer questions from your own documents, extraction of data from invoices and forms, and analysis of your history.</p>', '[{"title":"Decisions from facts","body":"Analysis built on clean, reconciled data from your own systems."},{"title":"Less manual capture","body":"Document processing extracts data from forms, receipts and invoices."},{"title":"Practical AI","body":"Assistants and automations are scoped to clear tasks, with human review where it matters."},{"title":"Your data stays yours","body":"We design for privacy and follow Zimbabwe’s Cyber and Data Protection Act."}]', '["Data audit and connection to your sources","AI assistant, analysis or document-processing workflow","Scheduled reports","Documentation of data flows and access"]', '[{"q":"Do we need a lot of data to use AI?","a":"Not always. Many useful features, such as document extraction or a question-answering assistant over your policies, work with the documents you already have."},{"q":"Is our data shared with anyone?","a":"Only with the services the solution needs to run, under agreements that protect it. We explain where your data goes in the written proposal."}]', 'line-chart', 'active', 1, 40, 'AI Integration, Data Intelligence & Document Processing', 'AI assistants built on your own content, data intelligence and analytics, and intelligent document processing for invoices and forms.')
  ON CONFLICT(id) DO UPDATE SET slug = excluded.slug, name = excluded.name, summary = excluded.summary, description = excluded.description, benefits = excluded.benefits, deliverables = excluded.deliverables, faq = excluded.faq, icon = excluded.icon, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, seo_title = excluded.seo_title, seo_description = excluded.seo_description, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now');
