  ON CONFLICT(id) DO UPDATE SET category_id = excluded.category_id, slug = excluded.slug, name = excluded.name, summary = excluded.summary, pricing_model = excluded.pricing_model, price_minor = excluded.price_minor, currency = excluded.currency, status = excluded.status, sort_order = excluded.sort_order, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now');
INSERT INTO service_categories (id, slug, name, summary, description, benefits, deliverables, faq, icon, status, featured, sort_order, seo_title, seo_description) VALUES ('scat_automation_integration', 'automation-integration', 'Automation & Integration', 'Workflows, payment gateways, APIs and integrations that remove manual steps between systems.', '<p>When systems do not talk to each other, people re-type data, chase approvals and reconcile by hand. We connect your systems through APIs and automate the repetitive steps in between.</p><p>We work with Zimbabwean payment rails, including EcoCash, OneMoney, InnBucks, O’mari and card payments, and build integrations that confirm every payment before it is recorded.</p>', '[{"title":"Fewer manual steps","body":"Automated workflows move data and approvals without re-typing."},{"title":"Reliable payments","body":"Gateway integrations verify every payment with the provider before marking it paid."},{"title":"Systems that agree","body":"Integrations keep records consistent across your tools."},{"title":"Room to change","body":"Clean, documented APIs make it easier to swap or add systems later."}]', '["Integration design and documentation","Automated workflows and notifications","Payment integration with confirmation and reconciliation","APIs with authentication","Error alerts and safe retries"]', '[{"q":"Can you add EcoCash and card payments to our existing website?","a":"Yes. Each local method (EcoCash, OneMoney, InnBucks or O’mari) is $50 and card payments are $100, including payment confirmation and receipts."},{"q":"What happens if an integration fails?","a":"Integrations retry safely and alert your team, so nothing is lost or processed twice."}]', 'workflow', 'active', 1, 50, 'Automation, Payment Gateway Integration & APIs', 'Business process automation, payment gateway integration for EcoCash, OneMoney, InnBucks, O’mari and cards, API development and systems integration.')
  ON CONFLICT(id) DO UPDATE SET slug = excluded.slug, name = excluded.name, summary = excluded.summary, description = excluded.description, benefits = excluded.benefits, deliverables = excluded.deliverables, faq = excluded.faq, icon = excluded.icon, status = excluded.status, featured = excluded.featured, sort_order = excluded.sort_order, seo_title = excluded.seo_title, seo_description = excluded.seo_description, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now');
